\caption{Solve simply-connected Dirichlet problem}
\label{alg:main}
\begin{algorithmic}[1]
\STATE Set the $z'_n$ to the initial guess, as explained in Section~\ref{ssec:initial}.
\WHILE {stopping criterion not met}
\STATE Solve~\eqref{eq:normalEquations} for the $a^{\mathrm{R}}_n$ and $a^{\mathrm{I}}_n$. Use only $z'_n \notin \Omega$.
\STATE Use the $a^{\mathrm{R}}_n$ and $a^{\mathrm{I}}_n$ to form $\widehat{V}$ according to~\eqref{eq:approxV} and $\widehat{W}$ according to~\eqref{eq:compPotToApprox}.
\STATE Form $\widehat{Q}$ according to~\eqref{eq:QHat}, use all $z'_n$.
\STATE Solve~\eqref{eq:Galerkin2} for $P$ and $Q$.
\STATE $z'_n = \text{roots}(Q)$.
\ENDWHILE
\end{algorithmic}

The inner product used in this work is
\begin{equation}\label{eq:ip}
    \left<u,v\right>_\Gamma = \int_0^1 u\left(z(s)\right)v^*\left(z(s)\right)\lambda(s)ds,
\end{equation}
where $\lambda(s)$ denotes a positive weight function, and $z(s)$ is a parametrization of $\Gamma$.

The least-squares solution to~\eqref{eq:LSLambda} is given analytically by
